do $$
declare
  v_course_id uuid := 'c2eca76b-a87d-4bbd-a537-58c25d90acfe';
  v_level uuid;
  -- modules.order_number is unique per COURSE, not per level (a course's
  -- modules are numbered continuously across all its levels) -- so this
  -- can't just start at 1 for a level beyond the first. Computed here
  -- instead of hardcoded so this script works correctly regardless of how
  -- many modules the course already has.
  v_module_offset int;
  v_m1 uuid;
  v_m2 uuid;
begin
  -- Appending to a level that already exists. Looked up rather than
  -- inserted, so this adds to the learner's current Level 1 instead of
  -- creating a duplicate one, and no existing module is re-parented.
  select id into v_level from public.levels
    where course_id = v_course_id and order_number = 1;

  if v_level is null then
    raise exception 'Level % not found for course % -- refusing to guess', 1, v_course_id;
  end if;

  -- The new modules must sit INSIDE this level, not at the end of the
  -- course. getOrderedLessons() builds the learner's lesson sequence from
  -- modules.order_number alone and ignores level, so a module appended at
  -- the course's max order would put beginner content after the final
  -- level's material. Insert straight after this level's last module and
  -- shift everything below it down instead.
  select coalesce(max(order_number), 0) into v_module_offset
    from public.modules where level_id = v_level;

  -- Two-phase shift: (course_id, order_number) is unique, and a single
  -- "+ N" update can trip that constraint mid-statement, so park the rows
  -- out of range first and bring them back afterwards.
  update public.modules set order_number = order_number + 1000
   where course_id = v_course_id and order_number > v_module_offset;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Before the Dashboard: Getting the Data Right', 'The existing lessons teach Power BI and Looker Studio. This one covers what happens before either of them opens — because a beautiful dashboard built on dirty data is confidently wrong.', v_module_offset + 1)
  returning id into v_m1;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m1, 'What Dirty Data Looks Like', 'Google''s Data Analytics programme on the errors that make data untrustworthy — spelling, inconsistent labels, missing values and duplicates. Under 7 minutes.', 'https://www.youtube.com/watch?v=0l_SlOq34Ug', 1,
      array['Recognise the common ways a dataset is dirty', 'Explain why one inconsistent label breaks an entire chart', 'Decide what to do about missing values instead of ignoring them'],
      'Analysts spend most of their time cleaning data, not visualising it. Beginners are always surprised by that, and it is the main reason a first real job feels nothing like a Power BI tutorial.

WHAT DIRTY DATA ACTUALLY LOOKS LIKE:

INCONSISTENT LABELS. "Nairobi", "nairobi", "NBO" and "Nairobi " with a trailing space are four different values to a computer. Your chart shows four cities. Nobody notices until someone asks why the total is wrong.

DUPLICATES. The same order counted twice inflates every number downstream. Duplicates usually arrive from merging two exports or re-running an import.

MISSING VALUES. Blank cells, or worse, someone typed "N/A", "none", "-" or 0. A zero is especially dangerous, because it looks like data and drags your averages down.

WRONG DATA TYPES. Numbers stored as text will not add up; dates stored as text sort alphabetically, so December comes before February. In spreadsheets this shows up as a value quietly left-aligned when it should be right-aligned.

DATE FORMAT CHAOS. 03/04/2026 is 3 April to a Kenyan and 4 March to an American, and a spreadsheet will happily mix both in one column. When you can, use YYYY-MM-DD.

OUTLIERS AND IMPOSSIBLE VALUES. An age of 300, a negative price, a sale dated next year. Check the minimum and maximum of every numeric column first — it takes seconds and catches a lot.

WHAT TO DO ABOUT MISSING VALUES is a judgement, not a rule. You can remove the rows, fill them with something defensible, or keep them and report the gap. What you must NOT do is silently pretend they were zero. WRITE DOWN what you decided, because whoever reads your chart will eventually ask.

AND KEEP THE ORIGINAL. Clean a COPY, never the raw file. The moment you overwrite the source, you can no longer prove what the data said before you touched it — and you will need to.',
      'Take any real spreadsheet you can find — an export, a class list, a sales sheet. Check five things and write down what you find: duplicate rows, a text column with inconsistent spellings or casing, blank cells, any column of numbers stored as text, and the minimum and maximum of each numeric column. Then write one sentence per problem saying what you would do about it. That written note is what separates an analyst from someone who made a chart.',
      '[{"question":"Why is \"Nairobi\" and \"nairobi\" in the same column a problem?","options":["The computer treats them as different values, so one city appears as several","It makes the file larger","Power BI cannot import lowercase text","It only matters if the column is sorted"],"correct_index":0},{"question":"What should you never do with missing values?","options":["Silently treat them as zero","Remove the affected rows and say so","Fill them with a defensible estimate and note it","Keep them and report the gap"],"correct_index":0}]'::jsonb),
    (v_m1, 'Cleaning It: Sorting, Filtering, Pivots and Lookups', 'Google''s Data Analytics programme on the actual techniques — sorting, filtering, pivot tables and VLOOKUP — that turn a messy export into something you can chart. About 10 minutes.', 'https://www.youtube.com/watch?v=sNqf977ojKg', 2,
      array['Sort and filter to isolate the rows that matter', 'Summarise data with a pivot table instead of by hand', 'Bring two datasets together with a lookup'],
      'The previous lesson was diagnosis. This one is treatment, and it happens in a spreadsheet far more often than in a BI tool — which is why every analyst job advert still asks for Excel or Sheets.

SORTING is the fastest bug-finder there is. Sort a column and the problems surface at the ends: blanks, impossible values, that one row where someone typed the name into the amount column. Do it on every column before you trust anything.

FILTERING answers most simple questions without any chart at all. How many sales in March? Filter and read the count. Analysts reach for a dashboard far too early; a filter often IS the analysis.

PIVOT TABLES are the single highest-value thing in this lesson. A pivot summarises thousands of rows into a small table — total sales per region, average score per class, count of orders per month — in about four clicks and with no formulas. If you learn one spreadsheet skill for employment, learn this one. Most "data analysis" asked of a junior is a pivot table with a sentence underneath.

LOOKUPS (VLOOKUP, or XLOOKUP where you have it) join two sheets: order rows here, customer details there, matched on a shared id. Real data almost always arrives split across files, and this is how you put it back together.

THE HABITS THAT SEPARATE CLEAN WORK FROM A MESS:
- Clean a COPY. Never the raw export.
- Keep a note of every change you made, in a tab or a text file. When a number is questioned three weeks later, that note is your answer.
- Do not delete rows you are unsure about — flag them in a new column instead, so the decision stays visible and reversible.
- Check the row count before and after. If cleaning changed it, know exactly why.

AND SANITY-CHECK THE RESULT against something you already know. If the total revenue is a tenth of what the business expects, you have a problem in your data, not an interesting insight. That reflex — does this number look plausible? — is what a manager is really hiring.',
      'Take the messy spreadsheet from the previous lesson. Sort every column and note what surfaces at the top and bottom. Then build one pivot table that answers a real question — total or average of one thing, grouped by another. Write the answer as a single sentence a non-technical person would understand. Note your row count before and after cleaning, and if it changed, write down why.',
      '[{"question":"Why is sorting a column such a useful first step?","options":["Problems collect at the extremes — blanks, impossible values, misplaced entries","It permanently fixes inconsistent spellings","Charts require sorted data","It removes duplicate rows automatically"],"correct_index":0},{"question":"Your cleaned total revenue is a tenth of what the business expects. What is the right conclusion?","options":["Something is wrong with your data or your steps — check before reporting","You have found a significant business insight","The business''s own figures must be wrong","Publish it and let the client investigate"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Charts That Tell the Truth', 'Both tools in this course will draw any chart you ask for, including a badly chosen one. Deciding which chart the data deserves is the skill neither tool provides.', v_module_offset + 2)
  returning id into v_m2;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m2, 'Choosing the Right Chart', 'Maven Analytics on the nine chart types that cover almost every real need, and which question each one answers. About 7 minutes.', 'https://www.youtube.com/watch?v=wTKT18kmWzI', 1,
      array['Match a chart type to the question being asked', 'Explain why a pie chart is usually the wrong choice', 'Choose a chart your reader can understand without explanation'],
      'Start from the QUESTION, never from the chart menu. Each shape answers a particular kind of question, and using the wrong one makes true data hard to read.

THE PRACTICAL MAPPING:

COMPARING things across categories — BAR CHART. Sales by region, votes by candidate. Horizontal bars when the labels are long, which in the real world they usually are. The bar chart is the most under-rated chart there is: it is almost never wrong.

CHANGE OVER TIME — LINE CHART. Months along the bottom, always in order. Never use a line for categories that have no natural order; the line implies a journey that does not exist.

RELATIONSHIP BETWEEN TWO NUMBERS — SCATTER PLOT. Does spending more on ads bring more sales? And remember: a relationship is not proof that one caused the other.

DISTRIBUTION — HISTOGRAM. Where do most values fall? An average alone hides this: two classes with the same mean score can look completely different, and the histogram is where you see it.

PARTS OF A WHOLE — a bar chart, honestly. Pie charts are hard to read because people compare angles badly, they fail entirely beyond about four slices, and any pie needing a legend has already failed. If you must, use one — but only for two or three parts.

THE RULES THAT MAKE A CHART READABLE:
- Label the axes. Every time.
- Sort bars by value, not alphabetically, unless the order itself means something.
- Include the units, and say what period the data covers.
- One idea per chart. Two lines is fine; nine is a wall of spaghetti nobody reads.
- Give it a title that states the FINDING, not the contents: "Sales fell 20% after June" beats "Monthly sales".

AND FOR THIS AUDIENCE: most people will read your chart on a phone. If the labels are unreadable at that size, the chart does not work, however good it looks on your laptop.',
      'Take one dataset and deliberately build the same finding three ways — a bar chart, a line chart and a pie chart. Look at all three and write one sentence on which communicates it fastest and why the other two fail. Then retitle the best one so the title states the finding rather than the subject. Finally, look at it on your phone.',
      '[{"question":"Which chart best shows a value changing over twelve months?","options":["A line chart, with time in order along the bottom","A pie chart of the twelve months","A scatter plot","A histogram"],"correct_index":0},{"question":"What makes a good chart title?","options":["It states the finding — \"Sales fell 20% after June\"","It states the contents — \"Monthly sales\"","It names the data source","It lists the chart type and date range"],"correct_index":0}]'::jsonb),
    (v_m2, 'How Charts Mislead — Including Yours', 'TED-Ed''s classic explainer on misleading graphs: the tricks that make true numbers tell a false story. About 4 minutes, and worth watching twice.', 'https://www.youtube.com/watch?v=E91bGT9BjYk', 2,
      array['Spot a truncated axis, a cherry-picked range and a misused scale', 'Check a chart before believing it, including your own', 'Present an honest chart even when the finding is inconvenient'],
      'This is the lesson that makes you employable rather than merely capable with the software, because it is about trust. Every technique below appears in charts made by well-meaning people who were not trying to deceive anyone.

THE TRUNCATED AXIS. Start the vertical axis at 97 instead of 0 and a rise from 98 to 99 looks like a doubling. For bar charts the axis should start at zero, full stop — the bar''s LENGTH is the message, so cutting it lies. Line charts have more latitude, but say what you did.

THE CHERRY-PICKED RANGE. Show the four months where the numbers rose and omit the year in which they fell. Nothing in the chart is false; the chart is. Always ask what happens just outside the edges.

THE WRONG SCALE. Doubling both the width and height of a picture to show "twice as much" actually shows four times the area, and the eye reads area. This is why 3D charts and picture-sized icons mislead so reliably.

CORRELATION PRESENTED AS CAUSE. Two lines rising together is not proof one caused the other. Ice cream sales and drownings both rise in hot weather.

COUNTS WHERE RATES BELONG. A bigger county reports more of everything. Per-capita or per-hundred is usually the honest comparison.

AND THE ONE MOST OFTEN DONE INNOCENTLY: a tiny sample presented as a trend. "Engagement up 50%" from six clicks to nine is noise, and saying so protects you far more than it costs you.

THE CHECK TO RUN ON YOUR OWN WORK, before you send anything: does the axis start at zero, would a wider date range change the story, is the sample big enough to mean anything, and does the title claim more than the data supports? A chart you would be comfortable defending line by line is the only kind worth attaching your name to — and in a field where the whole product is trust, that reputation is the asset.',
      'Find a chart in a newspaper, a company report or on social media and interrogate it: where does the axis start, what date range is shown, what is just outside that range, and how big is the sample? Write down whether it is honest, sloppy or deliberately misleading. Then take your own best chart from the previous lesson and run the same four checks on it. Fix whatever fails.',
      '[{"question":"Why must a bar chart''s vertical axis start at zero?","options":["The bar''s length carries the meaning, so truncating it exaggerates the difference","Charting tools require it","It makes the chart easier to colour","Only stacked bar charts need this"],"correct_index":0},{"question":"Engagement rose from six clicks to nine. What is the honest description?","options":["The sample is far too small to call it a trend","Engagement increased 50%","Engagement is growing steadily","The campaign was a clear success"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  -- Bring the shifted modules back, now sitting after the 2 new one(s).
  update public.modules set order_number = order_number - 1000 + 2
   where course_id = v_course_id and order_number > 1000;

end $$;
